SELECT
  SUM(CASE WHEN metric_time::date BETWEEN DATE '2026-07-06' AND DATE '2026-07-12' THEN value END) AS last_week_total,
  SUM(CASE WHEN metric_time::date BETWEEN DATE '2026-06-29' AND DATE '2026-07-05' THEN value END) AS prev_week_total
FROM (
  SELECT metric_time::date AS metric_time, value
  FROM (VALUES
    ('2026-07-11'::date,88),('2026-07-09'::date,95),('2026-07-06'::date,84),('2026-07-08'::date,80),('2026-07-10'::date,84),('2026-07-07'::date,113),('2026-07-12'::date,87),
    ('2026-07-01'::date,97),('2026-07-03'::date,104),('2026-07-05'::date,103),('2026-06-30'::date,100),('2026-07-04'::date,113),('2026-06-29'::date,108),('2026-07-02'::date,98)
  ) AS t(metric_time, value)
) x;

SELECT SUM(value) AS week_active_users FROM (
  SELECT metric_time__day, value
  FROM (
    SELECT metric_time__day, value
    FROM (VALUES
      (DATE '2026-07-06',98),(DATE '2026-07-07',106),(DATE '2026-07-08',108),(DATE '2026-07-09',78),(DATE '2026-07-10',92),(DATE '2026-07-11',88),(DATE '2026-07-12',98)
    ) AS t(metric_time__day, value)
  )
) ;

SELECT SUM(value) AS week_active_accounts FROM (
  SELECT metric_time__day, value
  FROM (VALUES
    (DATE '2026-07-06',101),(DATE '2026-07-07',110),(DATE '2026-07-08',109),(DATE '2026-07-09',81),(DATE '2026-07-10',98),(DATE '2026-07-11',93),(DATE '2026-07-12',101)
  ) AS t(metric_time__day, value)
) ;

SELECT SUM(value) FILTER (WHERE metric_name='value_moments') AS total_value_moments,
       SUM(value) FILTER (WHERE metric_name='active_users') AS total_active_users
FROM (
  SELECT metric_time__day, value, 'value_moments' as metric_name FROM (
    SELECT metric_time__day, value FROM (
      VALUES
      (DATE '2026-07-06',501),(DATE '2026-07-07',601),(DATE '2026-07-08',507),(DATE '2026-07-09',478),(DATE '2026-07-10',512),(DATE '2026-07-11',497),(DATE '2026-07-12',546)
    ) AS t(metric_time__day,value)
  )
  UNION ALL
  SELECT metric_time__day, value, 'active_users' as metric_name FROM (
    SELECT metric_time__day, value FROM (
      VALUES
      (DATE '2026-07-06',278),(DATE '2026-07-07',331),(DATE '2026-07-08',294),(DATE '2026-07-09',268),(DATE '2026-07-10',287),(DATE '2026-07-11',273),(DATE '2026-07-12',281)
    ) AS t(metric_time__day,value)
  )
) s;
